//! R036/09: Multi-file replace transaction on source tree. Real guest filesystem/workstation operation.
use super::Error;
use crate::batch7_ramfs::{RamFs,CONTENT_MAX,PATH_MAX};
pub fn replace<const F:usize,const B:usize>(fs:&mut RamFs<F>,root:&[u8],expected:u64,from:&[u8],to:&[u8])->Result<usize,Error>{if from.is_empty()||expected!=fs.version(){return Err(Error::Stale);}let mut original=[0;B];let n=fs.export_snapshot(&mut original).map_err(|_|Error::Full)?;let mut staged=RamFs::<F>::new();staged.import_snapshot(&original[..n]).map_err(|_|Error::Invalid)?;let mut files=0;for i in 0..fs.count(){let mut path=[0;PATH_MAX];let(len,size,_)=fs.entry(i,&mut path).map_err(|_|Error::Missing)?.ok_or(Error::Missing)?;if !path[..len].starts_with(root)||path.get(root.len())!=Some(&b'/')||!path[..len].ends_with(b".rs"){continue;}let mut data=[0;CONTENT_MAX];fs.read(&path[..len],0,&mut data[..size]).map_err(|_|Error::Missing)?;let mut updated=[0;CONTENT_MAX];let(mut i,mut w,mut hits)=(0,0,0);while i<size{let match_here=i+from.len()<=size&&&data[i..i+from.len()]==from;let chunk=if match_here{to}else{&data[i..i+1]};if w+chunk.len()>CONTENT_MAX{return Err(Error::Full);}updated[w..w+chunk.len()].copy_from_slice(chunk);w+=chunk.len();i+=if match_here{from.len()}else{1};hits+=usize::from(match_here);}if hits>0{staged.replace(&path[..len],&updated[..w]).map_err(|_|Error::Full)?;files+=1;}}if files>0{let mut image=[0;B];let n=staged.export_snapshot(&mut image).map_err(|_|Error::Full)?;fs.import_snapshot(&image[..n]).map_err(|_|Error::Invalid)?;}Ok(files)}
#[cfg(test)]mod tests{use super::*;#[test]fn real_functional_regression(){let mut fs=RamFs::<2>::new();fs.replace(b"/p/a.rs",b"old()").unwrap();fs.replace(b"/p/b.rs",b"old()").unwrap();assert_eq!(replace::<2,8192>(&mut fs,b"/p",2,b"old",b"new"),Ok(2));}}
